"""Intent tests for M1-T18: annualize volatility over trading days (RISK-03, TC-06)."""

import json
from pathlib import Path
from typing import Any

import pytest

from risk import Returns, VolSeries, annualize

ROOT = Path(__file__).resolve().parents[3]
TC06 = ROOT / "tests" / "fixtures" / "risk" / "TC-06"
VOL_SAMPLE = ROOT / "tests" / "contracts" / "risk.VolSeries" / "sample.json"


def _load(path: Path) -> Any:
    return json.loads(path.read_text())


def _vol_from_json(data: dict[str, Any]) -> VolSeries:
    r = data["returns"]
    returns = Returns(
        base_date=r["base_date"],
        dates=tuple(r["dates"]),
        tickers=tuple(r["tickers"]),
        values={t: tuple(v) for t, v in r["values"].items()},
    )
    return VolSeries(
        returns=returns,
        window=data["window"],
        annualized=data["annualized"],
        values={t: tuple(v) for t, v in data["values"].items()},
    )


@pytest.mark.intent
def test_tc06_values_scaled_and_gaps_kept() -> None:
    vol = _vol_from_json(_load(TC06 / "input.json")["vol"])
    expected = _load(TC06 / "expected.json")
    tol = expected["tol"]

    result = annualize(vol)

    assert set(result.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = result.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g is not None
                assert g == pytest.approx(w, abs=tol)


@pytest.mark.intent
def test_tc06_result_is_marked_annualized_and_keeps_alignment() -> None:
    vol = _vol_from_json(_load(TC06 / "input.json")["vol"])
    expected = _load(TC06 / "expected.json")

    result = annualize(vol)

    assert result.annualized is expected["annualized"]
    assert result.window == vol.window
    assert result.returns == vol.returns


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_value_error() -> None:
    already = _vol_from_json(_load(VOL_SAMPLE))
    assert already.annualized is True

    with pytest.raises(ValueError, match=r"(?i)annuali"):
        annualize(already)


@pytest.mark.intent
def test_annualizing_twice_is_value_error() -> None:
    vol = _vol_from_json(_load(TC06 / "input.json")["vol"])

    with pytest.raises(ValueError, match=r"(?i)annuali"):
        annualize(annualize(vol))

